		);
		if (!definition) throw new Error("create-routine definition is missing");
		const inputSchema = z.strictObject(definition.inputSchema);
		expect(() =>
			inputSchema.parse({
				routine: { title: "Push", folderId: 3, exercises: [] },
			}),
		).toThrow();
	});
});

