					count: 0,
					total_duration_seconds: 0,
					exercise_count: 0,
					set_count: 0,
					unique_exercise_template_ids: [],
					sessions: [],
				},
				body_measurements: { count: 0 },
			});
		} finally {
			vi.useRealTimers();
		}
	});
});

