					descriptor: workoutsListDescriptor,
					effect: vi.fn(),
					execute: vi.fn(),
				},
			},
			routines: {
				get: {
					descriptor: routinesGetDescriptor,
					effect: vi.fn(),
					execute: vi.fn(),
				},
				list: {
					descriptor: routinesListDescriptor,
					effect: vi.fn(),
					execute: vi.fn(),
				},
			},
			templates: {
				get: {
					descriptor: templatesGetDescriptor,
					effect: templateEffect,
					execute: vi.fn(),
